using UnityEngine;

namespace Framework.Sample
{
    /// <summary>
    /// サンプルコンポーネント。
    /// </summary>
    public class SampleController : MonoBehaviour
    {
        /// <summary>
        /// 移動速度。
        /// </summary>
        [Header("移動設定")]
        [SerializeField]
        [Range(0f, 10f)]
        [Tooltip("移動速度を設定する")]
        private float moveSpeed = 5f;

        /// <summary>
        /// 現在の移動速度を取得する。
        /// </summary>
        public float MoveSpeed => moveSpeed;

        /// <summary>
        /// 移動速度を更新する。
        /// </summary>
        /// <param name="speed">新しい移動速度</param>
        public void SetSpeed(float speed)
        {
            moveSpeed = Mathf.Clamp(speed, 0f, 10f);
        }
    }
}
